test('invoiceTotals returns integers', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 }]
  };
  const totals = invoiceTotals(invoice);
  assert.equal(Number.isInteger(totals.subtotal), true);
  assert.equal(Number.isInteger(totals.discount), true);
  assert.equal(Number.isInteger(totals.vat), true);
  assert.equal(Number.isInteger(totals.voucher), true);
  assert.equal(Number.isInteger(totals.total), true);
});

test('lineDiscount includes bulk discount for qty >= 10', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 };
  const discount = lineDiscount(line);
  const lineTotal = 1000;
  const bulkDiscount = Math.round(lineTotal * 2.5 / 100);
  assert.equal(discount, bulkDiscount);
});

test('lineDiscount no bulk discount for qty < 10', () => {
  const line = { qty: 9, unitPrice: 100, discountPercent: 0, vatRate: 0 };
  const discount = lineDiscount(line);
  assert.equal(discount, 0);
});

test('lineDiscount applies bulk discount after line discount', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 10, vatRate: 0 };
  const lineTotal = 1000;
  const firstDiscount = Math.round(lineTotal * 10 / 100);
  const amountAfterFirst = lineTotal - firstDiscount;
  const bulkDiscount = Math.round(amountAfterFirst * 2.5 / 100);
  const expectedTotal = firstDiscount + bulkDiscount;
  assert.equal(lineDiscount(line), expectedTotal);
});

test('lineDiscount with bulk discount exactly at threshold', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 };
  const discount = lineDiscount(line);
  assert.ok(discount > 0);
});

test('lineDiscount no bulk discount at qty 9', () => {
  const line = { qty: 9, unitPrice: 100, discountPercent: 0, vatRate: 0 };
  const discount = lineDiscount(line);
  assert.equal(discount, 0);
});

test('lineAmountAfterDiscount includes bulk discount', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 };
  const lineTotal = 1000;
  const bulkDiscount = Math.round(lineTotal * 2.5 / 100);
  const expected = lineTotal - bulkDiscount;
  assert.equal(lineAmountAfterDiscount(line), expected);
});

test('lineVat calculated on amount after bulk discount', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 };
  const lineTotal = 1000;
  const bulkDiscount = Math.round(lineTotal * 2.5 / 100);
  const amountAfterDiscount = lineTotal - bulkDiscount;
  const expectedVat = Math.round(amountAfterDiscount * 21 / 100);
  assert.equal(lineVat(line), expectedVat);
});

test('lineDiscount bulk discount with existing line discount', () => {
  const line = { qty: 20, unitPrice: 100, discountPercent: 5, vatRate: 0 };
  const lineTotal = 2000;
  const firstDiscount = Math.round(lineTotal * 5 / 100);
  const amountAfterFirst = lineTotal - firstDiscount;
  const bulkDiscount = Math.round(amountAfterFirst * 2.5 / 100);
  const totalDiscount = firstDiscount + bulkDiscount;
  assert.equal(lineDiscount(line), totalDiscount);
});

test('invoiceTotals includes bulk discount in discount field', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 }
    ]
  };
  const totals = invoiceTotals(invoice);
  const lineTotal = 1000;
  const expectedDiscount = Math.round(lineTotal * 2.5 / 100);
  assert.equal(totals.discount, expectedDiscount);
});

test('invoiceTotals with mixed qty including bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 },
      { qty: 5, unitPrice: 100, discountPercent: 0, vatRate: 0 }
    ]
  };
  const totals = invoiceTotals(invoice);
  const line1Total = 1000;
  const line1Discount = Math.round(line1Total * 2.5 / 100);
  assert.equal(totals.discount, line1Discount);
});

test('invoiceTotals total with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 }
    ]
  };
  const totals = invoiceTotals(invoice);
  const lineTotal = 1000;
  const bulkDiscount = Math.round(lineTotal * 2.5 / 100);
  const expected = lineTotal - bulkDiscount;
  assert.equal(totals.total, expected);
});

test('invoiceTotals with bulk discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 }
    ]
  };
  const totals = invoiceTotals(invoice);
  const lineTotal = 1000;
  const bulkDiscount = Math.round(lineTotal * 2.5 / 100);
  const amountAfterDiscount = lineTotal - bulkDiscount;
  const expectedVat = Math.round(amountAfterDiscount * 21 / 100);
  assert.equal(totals.vat, expectedVat);
});

test('bulk discount with large qty', () => {
  const line = { qty: 1000, unitPrice: 100, discountPercent: 0, vatRate: 0 };
  const discount = lineDiscount(line);
  const lineTotal = 100000;
  const expectedDiscount = Math.round(lineTotal * 2.5 / 100);
  assert.equal(discount, expectedDiscount);
});

test('bulk discount rounded correctly', () => {
  const line = { qty: 10, unitPrice: 123, discountPercent: 0, vatRate: 0 };
  const discount = lineDiscount(line);
  assert.equal(Number.isInteger(discount), true);
});

test('invoiceTotals discount combines line and bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, discountPercent: 10, vatRate: 0 }
    ]
  };
  const totals = invoiceTotals(invoice);
  const lineTotal = 1000;
  const firstDiscount = Math.round(lineTotal * 10 / 100);
  const amountAfterFirst = lineTotal - firstDiscount;
  const bulkDiscount = Math.round(amountAfterFirst * 2.5 / 100);
  const expectedTotal = firstDiscount + bulkDiscount;
  assert.equal(totals.discount, expectedTotal);
});

