import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineAmountAfterDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a valid invoice with one line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-01-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[0].qty, 10);
  assert.equal(result.value.lines[0].unitPrice, 8500);
  assert.equal(result.value.lines[0].vatRate, 21);
});

test('createInvoice normalizes customer ID', () => {
  const result = createInvoice({
    customerId: 'c-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID with whitespace', () => {
  const result = createInvoice({
    customerId: ' c-003 ',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
});

test('createInvoice defaults terms to NET30', () => {
