test('invoiceTotals includes voucher in return value', () => {
  const invoice = {
    lines: [{ qty: 8, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
    voucher: { code: 'SAVE10', amount: 500 },
  };
  const totals = invoiceTotals(invoice);
  assert.ok('voucher' in totals);
  assert.equal(totals.voucher, 500);
});

test('invoiceTotals calculates voucher correctly', () => {
  const invoice = {
    lines: [{ qty: 8, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totalsWithoutVoucher = invoiceTotals(invoice);

  const invoiceWithVoucher = {
    ...invoice,
    voucher: { code: 'SAVE10', amount: 2000 },
  };
  const totalsWithVoucher = invoiceTotals(invoiceWithVoucher);

  assert.equal(totalsWithVoucher.voucher, 2000);
  assert.equal(totalsWithVoucher.total, totalsWithoutVoucher.total - 2000);
});

test('applyVoucher adds voucher to draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });
  assert.equal(result.ok, true);

  const voucherResult = applyVoucher(result.value, { code: 'SAVE10', amount: 5000 });
  assert.equal(voucherResult.ok, true);
  assert.equal(voucherResult.value.voucher.code, 'SAVE10');
  assert.equal(voucherResult.value.voucher.amount, 5000);
});

test('applyVoucher rejects non-draft invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });
  assert.equal(result.ok, true);
  const issueResult = issueInvoice(result.value, []);
  const issuedInvoice = issueResult.value;

  assert.deepEqual(
    applyVoucher(issuedInvoice, { code: 'SAVE10', amount: 5000 }),
    { ok: false, error: 'NOT_DRAFT' }
  );
});

test('applyVoucher rejects if voucher already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });
  assert.equal(result.ok, true);
  let invoice = result.value;

  const voucherResult1 = applyVoucher(invoice, { code: 'SAVE10', amount: 5000 });
  assert.equal(voucherResult1.ok, true);
  invoice = voucherResult1.value;

  const voucherResult2 = applyVoucher(invoice, { code: 'SAVE20', amount: 10000 });
  assert.deepEqual(voucherResult2, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher requires positive integer amount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });
  assert.equal(result.ok, true);

  assert.deepEqual(
    applyVoucher(result.value, { code: 'ZERO', amount: 0 }),
    { ok: false, error: 'AMOUNT_INVALID' }
  );
  assert.deepEqual(
    applyVoucher(result.value, { code: 'NEG', amount: -1000 }),
    { ok: false, error: 'AMOUNT_INVALID' }
  );
  assert.deepEqual(
    applyVoucher(result.value, { code: 'DECIMAL', amount: 1000.5 }),
    { ok: false, error: 'AMOUNT_INVALID' }
  );
});

test('applyVoucher does not mutate input invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });
  assert.equal(result.ok, true);

  assert.ok(!result.value.voucher);
  applyVoucher(result.value, { code: 'SAVE10', amount: 5000 });
  assert.ok(!result.value.voucher);
});

test('voucher reduces total after discount and VAT', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 8, discountPercent: 10 }],
  });
  assert.equal(result.ok, true);
  let invoice = result.value;

  const totalsBeforeVoucher = invoiceTotals(invoice);

  const voucherResult = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });
  assert.equal(voucherResult.ok, true);
  invoice = voucherResult.value;

  const totalsAfterVoucher = invoiceTotals(invoice);

  assert.equal(totalsAfterVoucher.total, totalsBeforeVoucher.total - 10000);
});

test('voucher cannot reduce total below 0', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'STICKER', qty: 8, discountPercent: 0 }],
  });
  assert.equal(result.ok, true);
  let invoice = result.value;

  const totalsBeforeVoucher = invoiceTotals(invoice);

  const voucherResult = applyVoucher(invoice, { code: 'HUGE', amount: totalsBeforeVoucher.total + 100000 });
  assert.equal(voucherResult.ok, true);
  invoice = voucherResult.value;

  const totalsAfterVoucher = invoiceTotals(invoice);
  assert.equal(totalsAfterVoucher.total, 0);
});

